#!/bin/sh
# tools/saehost.sh — build an app's own sae: sae with the app's native
# modules compiled in (docs/natives.md).
#
#   tools/saehost.sh <app-dir> [out-dir]
#   AETHER_UI_WITH_DRIVER=1 tools/saehost.sh <app-dir>    sae-driver too
#
# The app's app.json declares its native modules under "natives"; this
# stages a build of sae in <out-dir> (default target/hosts/<slug>) with
# sae's own sources linked in and two folders of the app's:
#
#   natives/module.ae          generated by saenatives: the dispatch to the
#                              app's modules, in place of sae's stub
#   app_natives/<name>/        each module, copied, checked by saenatives to
#     module.ae                need no capability at all
#
# then builds it as ./build.sh builds sae, to <out-dir>/target/build/bin/sae
# (and sae-driver). Run the app on it: <out-dir>/target/build/bin/sae --app
# <app-dir>. A module that needs a capability (files, network, clock,
# system, extern C) is refused, and nothing is built.
#
# The binary is sae as it is plus the app's modules, linked in at build
# time: nothing is loaded when the app runs. On iOS, where an app may not
# load code, the same holds: the modules are compiled into the one binary
# (docs/natives.md, "iOS").
set -eu
ROOT=$(cd "$(dirname "$0")/.." && pwd)
src="${1:?usage: saehost.sh <app-dir> [out-dir]}"
src=$(cd "$src" && pwd)
[ -f "$src/app.json" ] || { echo "saehost: $src has no app.json" >&2; exit 2; }

# Same toolchain as build.sh: an Aether dev tree beside sae wins.
if [ "${SAE_AETHER_HOME:-}" = none ]; then
    unset SAE_AETHER_HOME
elif [ -z "${SAE_AETHER_HOME:-}" ] && [ -f "$ROOT/../aether/build/libaether.a" ]; then
    SAE_AETHER_HOME=$(cd "$ROOT/../aether" && pwd)
fi
if [ -n "${SAE_AETHER_HOME:-}" ]; then
    export SAE_AETHER_HOME
    export AETHER_HOME="$SAE_AETHER_HOME"
    PATH="$SAE_AETHER_HOME/build:$PATH"
else
    # build.sh in the stage must not take the stage's ../aether for a dev tree.
    export SAE_AETHER_HOME=none
fi
PATH="$ROOT/target/toolchain/bin:$PATH"
export PATH

name=$(sed -n 's/^[[:space:]]*"name"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$src/app.json" | head -1)
[ -n "$name" ] || name=$(basename "$src")
slug=$(printf '%s' "$name" | tr 'A-Z' 'a-z' | tr -c 'a-z0-9_\n' '_' | sed 's/^_*//;s/_*$//')
[ -n "$slug" ] || slug=app
out="${2:-$ROOT/target/hosts/$slug}"
mkdir -p "$out"
out=$(cd "$out" && pwd)

# saenatives: the app's modules checked and copied, the dispatch written.
tool="$ROOT/target/saenatives"
if [ ! -x "$tool" ] || [ "$ROOT/tools/saenatives.ae" -nt "$tool" ]; then
    ae build "$ROOT/tools/saenatives.ae" -o "$tool" >/dev/null
fi
rm -rf "$out/natives" "$out/app_natives"
"$tool" "$src" "$out"

# The stage: sae's sources, linked; its own target for the build's output
# and cache.
# The build files are copied, not linked: aeb takes a build file's own
# folder for the project's, and its outputs and cache go there.
for f in src services lower aevg lib tools aether-ui ui vg pins; do
    rm -f "$out/$f"
    ln -s "$ROOT/$f" "$out/$f"
done
for f in build.sh .build.ae; do
    rm -f "$out/$f"
    cp "$ROOT/$f" "$out/$f"
done
cd "$out"
env -u AETHER_UI_WITH_DRIVER sh ./build.sh
if [ -n "${AETHER_UI_WITH_DRIVER:-}" ]; then
    AETHER_UI_WITH_DRIVER=1 sh ./build.sh
fi
echo "saehost: $out/target/build/bin/sae (the app $name, its natives compiled in)"
